const canSwitchStore = (): boolean => {
  if (isAdmin()) return true;
  return userRole?.can_change_store ?? false;
};

const canSelectStoreNF = (): boolean => {
  return isAdmin() || profileSelectStoreNF;
};

const refreshPermissions = async () => {
  await fetchUserPermissions();
};

const value: PermissionsContextType = {
  permissions,
  userRole,
  loading,
  hasPermission,
  hasAnyPermission,
  isAdmin,
  canAccessModule,
  refreshPermissions,
  canViewFinanceiro,
  canViewDashboard,
  canViewEstoque,
  canAdminPermissions,
  canViewLogistica,
  canViewRequisicao,
  canViewNotasFiscais,

  canViewEncomendas,
  canViewNCM,
  canViewEventos,
  canViewProntaEntrega: () => hasPermission('view_pronta_entrega') || isAdmin(),
  canViewMia: () => isAdmin(), // MIA visível APENAS para administradores
  canSwitchStore,
  canSelectStoreNF,
};

